 chart:<><path d=\"M4 4v16h17M8 15l4-5 4 3 5-7\"/></>, report:<><rect x=\"5\" y=\"3\" width=\"14\" height=\"18\" rx=\"2\"/><path d=\"M9 8h6M9 12h6M9 16h4\"/></>, users:<><circle cx=\"10\" cy=\"8\" r=\"3\"/><path d=\"M4 20v-2a6 6 0 0112 0v2M17 5a3 3 0 010 6m2 4a5 5 0 012 5\"/></>, settings:<><path d=\"m10 3-.7 2.2-2 .9-2.1-.5-2 3.4 1.5 1.7v2.6L3.2 15l2 3.4 2.2-.5 2 .9.6 2.2h4l.7-2.2 2-.9 2.1.5 2-3.4-1.5-1.7v-2.6L20.8 9l-2-3.4-2.2.5-2-.9L14 3z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></>, help:<><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M9.5 9a2.5 2.5 0 015 0c0 2-2.5 2-2.5 4m0 3h.01\"/></>, chevron:<path d=\"m9 5 7 7-7 7\"/>, plus:<path d=\"M12 5v14M5 12h14\"/>, search:<><circle cx=\"10.5\" cy=\"10.5\" r=\"6.5\"/><path d=\"m16 16 4 4\"/></>, bell:<><path d=\"M18 8a6 6 0 00-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4\"/></>, arrow:<path d=\"m6 15 5-5 4 3 5-7m-5 0h5v5\"/>, download:<><path d=\"M12 3v12m-4-4 4 4 4-4M4 15v5h16v-5\"/></>, calendar:<><rect x=\"3\" y=\"5\" width=\"18\" height=\"16\" rx=\"2\"/><path d=\"M7 3v4m10-4v4M3 10h18m-14 4h2m3 0h2m3 0h1m-11 3h2m3 0h2\"/></>, sliders:<><path d=\"M4 7h9m4 0h3M4 17h3m4 0h9\"/><circle cx=\"15\" cy=\"7\" r=\"2\"/><circle cx=\"9\" cy=\"17\" r=\"2\"/></>, more:<><circle cx=\"5\" cy=\"12\" r=\"1\"/><circle cx=\"12\" cy=\"12\" r=\"1\"/><circle cx=\"19\" cy=\"12\" r=\"1\"/></>, grip:<>{[8,16].map(x=>[5,12,19].map(y=><circle key={"'`${x}${y}`} cx={x} cy={y} r="1"/>))}</>, close:<path d="m6 6 12 12M6 18 18 6"/>, check:<path d="m5 12 4 4L19 6"/>, wallet:<><rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 8V5a2 2 0 012-2h12M21 11h-6v5h6m-3-2.5h.01"/></>, bag:<><path d="M5 7h14l2 14H3L5 7Z M8 8V6a4 4 0 018 0v2"/></>, target:<><circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/></>, external:<><path d="M14 3h7v7m0-7L10 14M10 5H4v15h15v-6"/></>, clock:<><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></>, logout:<><path d="M9 4H4v16h5m6-13 5 5-5 5m-7-5h12"/></>, reset:<><path d="M4 10a8 8 0 118 10M4 4v6h6"/></>
};
function Icon({name,size=20,className='"''}:{name:IconName,size?:number,className?:string}){return <svg className={className} width={size} height={size} viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.65\" strokeLinecap=\"round\" strokeLinejoin=\"round\" aria-hidden=\"true\">{paths[name]}</svg>}

type WidgetKind='revenue'|'visitors'|'orders'|'conversion'|'chart'|'traffic'|'recent'|'activity'|'goal'|'notes';
type Widget={id:string;kind:WidgetKind;x:number;y:number;w:number;h:number};
const initial:Widget[]=[{id:'revenue',kind:'revenue',x:0,y:0,w:3,h:2},{id:'visitors',kind:'visitors',x:3,y:0,w:3,h:2},{id:'orders',kind:'orders',x:6,y:0,w:3,h:2},{id:'conversion',kind:'conversion',x:9,y:0,w:3,h:2},{id:'chart',kind:'chart',x:0,y:2,w:8,h:4},{id:'traffic',kind:'traffic',x:8,y:2,w:4,h:4},{id:'recent',kind:'recent',x:0,y:6,w:8,h:4},{id:'activity',kind:'activity',x:8,y:6,w:4,h:4}];
const titles:Record<WidgetKind,string>={revenue:'Общая выручка',visitors:'Посетители',orders:'Заказы',conversion:'Конверсия',chart:'Динамика выручки',traffic:'Источники трафика',recent:'Последние заказы',activity:'Активность',goal:'Цель месяца',notes:'Заметки'};
const kindIcons:Record<WidgetKind,IconName>={revenue:'wallet',visitors:'users',orders:'bag',conversion:'target',chart:'chart',traffic:'users',recent:'report',activity:'clock',goal:'target',notes:'report'};
const orders=[{id:'#ORD-1028',name:'Александр Иванов',email:'alex.ivanov@mail.ru',initials:'АИ',color:'lavender',product:'Тариф «Бизнес»',date:'24 июн, 14:32',amount:'12 900 ₽',status:'Оплачен'},{id:'#ORD-1027',name:'Мария Смирнова',email:'m.smirnova@gmail.com',initials:'МС',color:'peach',product:'Тариф «Команда»',date:'24 июн, 13:18',amount:'6 900 ₽',status:'Оплачен'},{id:'#ORD-1026',name:'Дмитрий Козлов',email:'d.kozlov@mail.ru',initials:'ДК',color:'blue',product:'Тариф «Старт»',date:'24 июн, 12:45',amount:'2 900 ₽',status:'В обработке'},{id:'#ORD-1025',name:'Анна Петрова',email:'anna.p@yandex.ru',initials:'АП',color:'pink',product:'Тариф «Бизнес»',date:'24 июн, 11:06',amount:'12 900 ₽',status:'Оплачен'}];
function loadLayout():Widget[]{try{const a=JSON.parse(localStorage.getItem('forma-layout')||'null');if(Array.isArray(a)&&a.every(w=>titles[w.kind as WidgetKind]&&Number.isFinite(w.x)&&Number.isFinite(w.y)&&w.w>=2&&w.w<=12&&w.h>=2&&w.x>=0&&w.x+w.w<=12&&w.y>=0))return a}catch{}return initial}
function overlaps(a:Widget,b:Widget){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y}
function resolveLayout(layout:Widget[],moved:Widget){const result=layout.map(w=>w.id===moved.id?moved:{...w});const queue=[moved];let count=0;while(queue.length&&count++<100){const a=queue.shift()"'!;for(const b of result){if(b.id!==a.id&&b.id!==moved.id&&overlaps(a,b)){b.y=a.y+a.h;queue.push(b)}}}return result}
function Sparkline({variant=0}:{variant?:number}){const points=['"'0,34 9,31 17,33 27,23 36,25 45,19 55,23 64,10 73,13 82,6 91,9 100,2','0,33 10,30 20,32 30,22 39,25 49,17 58,20 67,10 78,14 88,5 100,8','0,34 11,28 20,30 31,21 42,26 51,14 62,18 72,8 84,13 92,3 100,6','0,34 10,29 20,31 32,21 41,24 52,18 63,22 73,10 84,14 93,5 100,7'][variant];return <svg className=\"sparkline\" viewBox=\"0 0 100 42\"><defs><linearGradient id={"'`spark${variant}`} x1="0" y1="0" x2="0" y2="1"><stop stopColor="#9a79ed" stopOpacity=".15"/><stop offset="1" stopColor="#9a79ed" stopOpacity="0"/></linearGradient></defs><polygon points={`0,42 ${points} 100,42`} fill={`url(#spark${variant})`}/><polyline points={points} fill="none" stroke="#9672e8" strokeWidth="1.8" strokeLinejoin="round"/></svg>}

export function App(){
 const [layout,setLayout]=useState<Widget[]>(loadLayout);const [editing,setEditing]=useState(false);const [modal,setModal]=useState<string|null>(null);const [popover,setPopover]=useState<string|null>(null);const [period,setPeriod]=useState('"'month');const [activeNav,setActiveNav]=useState('Мой дашборд');const [toast,setToast]=useState('');const [search,setSearch]=useState('');const [widgetSearch,setWidgetSearch]=useState('');const [chartPeriod,setChartPeriod]=useState('День');const [notes,setNotes]=useState(()=>localStorage.getItem('forma-notes')||'Запустить новую кампанию ✨\\nОбсудить результаты месяца с командой');const [dragId,setDragId]=useState<string|null>(null);const [mobileNav,setMobileNav]=useState(false);const [selectedOrder,setSelectedOrder]=useState(orders[0]);const [settingsName,setSettingsName]=useState(()=>localStorage.getItem('forma-name')||'Мой дашборд');
 const gridRef=useRef<HTMLDivElement>(null);const [gridWidth,setGridWidth]=useState(1000);const drag=useRef<{id:string;startX:number;startY:number;original:Widget;layout:Widget[];resize:boolean;current:Widget}|null>(null);
 useEffect(()=>{try{localStorage.setItem('forma-layout',JSON.stringify(layout))}catch{}},[layout]);
 useEffect(()=>{if("'!toast)return;const id=setTimeout(()=>setToast('"''),3500);return()=>clearTimeout(id)},[toast]);
 useEffect(()=>{const el=gridRef.current;if("'!el)return;const observer=new ResizeObserver(e=>setGridWidth(e[0].contentRect.width));observer.observe(el);return()=>observer.disconnect()},[]);
 useEffect(()=>{function key(e:KeyboardEvent){if((e.metaKey||e.ctrlKey)&&e.key==='"'k'){e.preventDefault();setModal('search')}if(e.key==='Escape'){setModal(null);setPopover(null);setEditing(false)}}window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key)},[]);
 const narrow=gridWidth<650;const step=(gridWidth+18)/12;
 function startDrag(e:React.PointerEvent,w:Widget,resize=false){if(narrow)return;e.preventDefault();e.stopPropagation();e.currentTarget.setPointerCapture(e.pointerId);drag.current={id:w.id,startX:e.clientX,startY:e.clientY,original:{...w},layout:layout.map(i=>({...i})),resize,current:w};setDragId(w.id);setEditing(true)}
 function moveDrag(e:React.PointerEvent){const d=drag.current;if("'!d)return;const dx=Math.round((e.clientX-d.startX)/step),dy=Math.round((e.clientY-d.startY)/82);const w=d.resize?{...d.original,w:Math.max(3,Math.min(12-d.original.x,d.original.w+dx)),h:Math.max(2,Math.min(8,d.original.h+dy))}:{...d.original,x:Math.max(0,Math.min(12-d.original.w,d.original.x+dx)),y:Math.max(0,d.original.y+dy)};d.current=w;setLayout(resolveLayout(d.layout,w))}
 function endDrag(){if(drag.current){drag.current=null;setDragId(null)}}
 function moveKeyboard(e:React.KeyboardEvent,w:Widget){if(!e.key.startsWith('"'Arrow'))return;e.preventDefault();setEditing(true);setLayout(resolveLayout(layout,{...w,x:Math.min(12-w.w,Math.max(0,w.x+(e.key==='ArrowRight'?1:e.key==='ArrowLeft'?-1:0))),y:Math.max(0,w.y+(e.key==='ArrowDown'?1:e.key==='ArrowUp'?-1:0))}))}
 function addWidget(kind:WidgetKind){const y=Math.max(0,...layout.map(w=>w.y+w.h));const stat=['revenue','visitors','orders','conversion'].includes(kind);setLayout([...layout,{id:"'`${kind}-${Date.now()}`,kind,x:0,y,w:stat?3:kind==='"'chart'||kind==='recent'?8:4,h:stat?2:4}]);setModal(null);setEditing(true);setToast('Виджет добавлен на дашборд')}
 function exportData(){const csv='\\uFEFFЗаказ;Клиент;Тариф;Сумма;Статус\\n'+orders.map(o=>[o.id,o.name,o.product,o.amount,o.status].join(';')).join('\\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='forma-orders.csv';a.click();URL.revokeObjectURL(a.href);setToast('Отчёт экспортирован в CSV');setPopover(null)}
 const factor=period==='week'?.26:period==='today'?.042:1;
 const metrics:Record<string,{value:string;change:string;foot:string;variant:number}>={revenue:{value:"'`${Math.round(1245800*factor).toLocaleString('"'ru-RU')} ₽"'`,change:'"'+18,6%',foot:'к прошлому периоду',variant:0},visitors:{value:Math.round(24892*factor).toLocaleString('ru-RU'),change:'+12,8%',foot:'к прошлому периоду',variant:1},orders:{value:Math.round(1432*factor).toLocaleString('ru-RU'),change:'+8,2%',foot:'к прошлому периоду',variant:2},conversion:{value:period==='week'?'5,42%':period==='today'?'5,68%':'5,75%',change:'+1,2%',foot:'к прошлому периоду',variant:3}};
 const displayed=layout.filter(w=>activeNav==='Аналитика'?['chart','traffic','revenue','visitors','conversion','goal'].includes(w.kind):activeNav==='Отчёты'?['recent','revenue','orders'].includes(w.kind):true);
 const visibleLayout=activeNav==='Аналитика'||activeNav==='Отчёты'?displayed.map((w,i)=>({...w,x:0,y:displayed.slice(0,i).reduce((n,v)=>n+v.h,0),w:12})):displayed;
 function navigate(name:string){setActiveNav(name);setMobileNav(false);setPopover(null)}
 function renderWidget(w:Widget){
 if(metrics[w.kind]){const m=metrics[w.kind];return <><div className=\"metric-title\"><span className={"'`metric-icon ${w.kind}`}><Icon name={kindIcons[w.kind]} size={17}/></span><span>{titles[w.kind]}</span></div><div className="metric-value">{m.value}</div><div className="metric-bottom"><span className="positive"><Icon name="arrow" size={13}/>{m.change}</span><span className="metric-foot">{m.foot}</span></div><Sparkline variant={m.variant}/></>}
 if(w.kind==='"'chart')return <><div className=\"card-heading\"><div><h3>Динамика выручки</h3><p>Ваш бизнес в цифрах</p></div><div className=\"segmented\">{['День','Неделя','Месяц'].map(t=><button key={t} className={chartPeriod===t?'selected':''} onClick={()=>setChartPeriod(t)}>{t}</button>)}</div></div><div className=\"chart-summary\"><strong>{metrics.revenue.value}</strong><span className=\"growth-badge\"><Icon name=\"arrow\" size={13}/>18,6%</span><div className=\"chart-legend\"><span><i/>Текущий период</span><span><i/>Прошлый период</span></div></div><RevenueChart period={chartPeriod} factor={factor}/></>;
 if(w.kind==='traffic')return <><div className=\"card-heading\"><div><h3>Источники трафика</h3><p>Откуда приходят посетители</p></div></div><div className=\"traffic-content\"><div className=\"donut\"><svg viewBox=\"0 0 160 160\"><circle cx=\"80\" cy=\"80\" r=\"61\" fill=\"none\" stroke=\"#f2f0f6\" strokeWidth=\"19\"/>{[{color:'#8b5de0',n:44,offset:0},{color:'#b49ae9',n:28,offset:44},{color:'#d4c3f1',n:18,offset:72},{color:'#ece5f7',n:10,offset:90}].map(s=><circle key={s.color} cx=\"80\" cy=\"80\" r=\"61\" fill=\"none\" stroke={s.color} strokeWidth=\"19\" pathLength=\"100\" strokeDasharray={"'`${s.n-1.5} ${101.5-s.n}`} strokeDashoffset={-s.offset} transform="rotate(-90 80 80)"/>)}</svg><div><strong>{metrics.visitors.value}</strong><span>посетителей</span></div></div><div className="traffic-legend">{[['"'Поиск','44%','#8b5de0'],['Прямые','28%','#b49ae9'],['Соцсети','18%','#d4c3f1'],['Другое','10%','#ece5f7']].map(r=><div key={r[0]}><span><i style={{background:r[2]}}/>{r[0]}</span><b>{r[1]}</b></div>)}</div></div><div className=\"card-footer\"><span><span className=\"tiny-dot\"/>4 активных источника</span><button onClick={()=>setModal('traffic')}>Подробнее <Icon name=\"chevron\" size={14}/></button></div></>;
 if(w.kind==='recent')return <><div className=\"card-heading\"><div className=\"heading-inline\"><h3>Последние заказы</h3><span className=\"count-badge\">{Math.round(1432*factor).toLocaleString('ru-RU')}</span></div><button className=\"text-button\" onClick={()=>setModal('orders')}>Все заказы <Icon name=\"chevron\" size={14}/></button></div><div className=\"table-wrap\"><table><thead><tr><th>Клиент</th><th>Заказ</th><th>Сумма</th><th>Статус</th></tr></thead><tbody>{orders.map(o=><tr key={o.id} onClick={()=>{setSelectedOrder(o);setModal('order')}} tabIndex={0} onKeyDown={e=>{if(e.key==='Enter'){setSelectedOrder(o);setModal('order')}}}><td><div className=\"customer\"><span className={"'`avatar ${o.color}`}>{o.initials}</span><div><strong>{o.name}</strong><small>{o.email}</small></div></div></td><td className="order-id">{o.id}<small>{o.date}</small></td><td className="amount">{o.amount}</td><td><span className={`status ${o.status==='"'Оплачен'?'paid':'pending'}"'`}><i/>{o.status}</span></td></tr>)}</tbody></table></div></>;
 if(w.kind==='"'activity')return <><div className=\"card-heading\"><h3>Активность</h3><span className=\"live\"><i/>В реальном времени</span></div><div className=\"activity-list\">{[{icon:'bag' as IconName,color:'lavender',title:'Новый заказ',desc:'Александр Иванов · 12 900 ₽',time:'2 минуты назад'},{icon:'users' as IconName,color:'blue',title:'Новый пользователь',desc:'Мария присоединилась к команде',time:'18 минут назад'},{icon:'target' as IconName,color:'green',title:'Цель достигнута',desc:'Более 1 000 заказов в этом месяце',time:'1 час назад'}].map((a,i)=><div className=\"activity-item\" key={a.title}><span className={"'`activity-icon ${a.color}`}><Icon name={a.icon} size={17}/></span><div><strong>{a.title}{i===0&&<i className="new-dot"/>}</strong><p>{a.desc}</p><small>{a.time}</small></div></div>)}</div><div className="card-footer activity-footer"><button onClick={()=>setModal('"'activity')}>Вся активность <Icon name=\"chevron\" size={14}/></button></div></>;
 if(w.kind==='goal')return <><div className=\"card-heading\"><h3>Цель месяца</h3><Icon name=\"target\"/></div><div className=\"goal-body\"><span className=\"goal-icon\"><Icon name=\"target\" size={38}/></span><strong>83%</strong><p>До цели осталось совсем немного</p><div className=\"progress\"><i/></div><span>1 245 800 ₽ <b>из 1 500 000 ₽</b></span></div></>;
 return <><div className=\"card-heading\"><h3>Заметки</h3><Icon name=\"report\" size={18}/></div><textarea className=\"notes\" aria-label=\"Ваши заметки\" value={notes} onChange={e=>{setNotes(e.target.value);localStorage.setItem('forma-notes',e.target.value)}} placeholder=\"Запишите что-нибудь важное…\"/><div className=\"notes-saved\"><Icon name=\"check\" size={13}/>Сохраняется автоматически</div></>;
 }
 return <div className=\"app-shell\">
 <aside className={"'`sidebar ${mobileNav?'"'mobile-open':''}"'`}><a className="brand" href="#" onClick={e=>{e.preventDefault();navigate('"'Мой дашборд')}}><span className=\"brand-symbol\"><i/><i/><i/><i/></span>forma<span className=\"brand-dot\">.</span></a><button className=\"workspace\" onClick={()=>setPopover(popover==='workspace'?null:'workspace')}><span className=\"workspace-logo\">S<span>✦</span></span><span><strong>Studio workspace</strong><small>Тариф Pro <span className=\"pro-dot\"/></small></span><Icon name=\"chevron\" size={15}/></button>{popover==='workspace'&&<div className=\"workspace-pop popover\"><strong>Рабочие пространства</strong><button onClick={()=>{setPopover(null);setToast('Вы в рабочем пространстве Studio')}}><Icon name=\"check\" size={16}/>Studio workspace</button><button onClick={()=>{setPopover(null);setModal('workspace')}}><Icon name=\"plus\" size={16}/>Новое пространство</button></div>}
 <div className=\"nav-section-label\">РАБОЧЕЕ ПРОСТРАНСТВО</div><nav>{([['Мой дашборд','grid'],['Аналитика','chart'],['Отчёты','report']] as [string,IconName][]).map(([label,icon])=><button key={label} className={activeNav===label?'active':''} onClick={()=>navigate(label)}><Icon name={icon}/><span>{label}</span>{label==='Мой дашборд'&&<span className=\"nav-count\">{layout.length}</span>}</button>)}</nav>
